  const count = {}; SOURCES.forEach(s => new Set(words(s)).forEach(w => count[w] = (count[w] || 0) + 1));
  const STOP = new Set(['part', 'chapter', 'with', 'from', 'the', 'and', 'for', 'των', 'στην', 'στον', 'για', 'απο', 'και', 'μαθημα', 'course', 'notes']);   // i18n-ignore
